using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string userId = args["userId"].ToString();
        string userName = args["userName"].ToString();

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        if (!File.Exists(dataPath)) {
            CPH.SendMessage($"@{userName}, you need to earn some eggs first! Chat to get started.");
            return false;
        }

        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        // Check user exists and has tokens
        if (data["users"] == null || data["users"][userId] == null) {
            CPH.SendMessage($"@{userName}, you need D20 Tokens to adventure! Use !buyD20 to purchase them (100 eggs per token).");
            return false;
        }

        int d20Tokens = (int)(data["users"][userId]["d20Tokens"] ?? 0);

        if (d20Tokens < 1) {
            CPH.SendMessage($"@{userName}, you need at least 1 D20 Token to adventure! Use !buyD20 to purchase (100 eggs per token).");
            return false;
        }

        // Check 24-hour cooldown
        string lastAdventureStr = data["users"][userId]["lastAdventure"]?.ToString() ?? "";
        if (!string.IsNullOrEmpty(lastAdventureStr)) {
            DateTime lastAdventure = DateTime.Parse(lastAdventureStr);
            TimeSpan timeSince = DateTime.UtcNow - lastAdventure;

            if (timeSince.TotalHours < 24) {
                double hoursLeft = 24 - timeSince.TotalHours;
                CPH.SendMessage($"@{userName}, your next adventure will be ready in {hoursLeft:F1} hours! (24h cooldown)");
                return false;
            }
        }

        // Load adventure stories
        string storiesPath = @"C:\StreamerBot\UserData\adventure-stories.json";
        if (!File.Exists(storiesPath)) {
            CPH.SendMessage($"@{userName}, adventure stories not found! Please set up adventure-stories.json.");
            return false;
        }

        string storiesJson = File.ReadAllText(storiesPath);
        JObject stories = JObject.Parse(storiesJson);
        JArray adventures = (JArray)stories["adventures"];

        if (adventures == null || adventures.Count == 0) {
            CPH.SendMessage($"@{userName}, no adventures available!");
            return false;
        }

        // Select adventure
        Random rnd = new Random();
        JObject adventure;

        // Check if user has a current adventure state
        string currentState = data["users"][userId]["adventureState"]?.ToString() ?? "";

        if (!string.IsNullOrEmpty(currentState)) {
            // Try to find next adventure from previous state
            var prevAdventure = adventures.FirstOrDefault(a => a["id"].ToString() == currentState);
            if (prevAdventure != null && prevAdventure["nextAdventures"] != null) {
                JArray nextIds = (JArray)prevAdventure["nextAdventures"];
                if (nextIds.Count > 0) {
                    string nextId = nextIds[rnd.Next(nextIds.Count)].ToString();
                    adventure = (JObject)adventures.FirstOrDefault(a => a["id"].ToString() == nextId);
                    if (adventure == null) {
                        adventure = (JObject)adventures[rnd.Next(adventures.Count)];
                    }
                } else {
                    adventure = (JObject)adventures[rnd.Next(adventures.Count)];
                }
            } else {
                adventure = (JObject)adventures[rnd.Next(adventures.Count)];
            }
        } else {
            // New adventurer - start with any adventure
            adventure = (JObject)adventures[rnd.Next(adventures.Count)];
        }

        // Deduct D20 token
        data["users"][userId]["d20Tokens"] = d20Tokens - 1;

        // Set up adventure state
        string adventureId = adventure["id"].ToString();
        string title = adventure["title"].ToString();
        string description = adventure["description"].ToString();
        string challenge = adventure["challenge"].ToString();
        int dc = (int)adventure["dc"];

        // Store active adventure
        if (data["activeAdventures"] == null) {
            data["activeAdventures"] = new JObject();
        }

        data["activeAdventures"][userId] = new JObject();
        data["activeAdventures"][userId]["adventureId"] = adventureId;
        data["activeAdventures"][userId]["challenge"] = challenge;
        data["activeAdventures"][userId]["dc"] = dc;
        data["activeAdventures"][userId]["successOutcome"] = adventure["successOutcome"].ToString();
        data["activeAdventures"][userId]["failureOutcome"] = adventure["failureOutcome"].ToString();
        data["activeAdventures"][userId]["successReward"] = (int)adventure["successReward"];
        data["activeAdventures"][userId]["failureReward"] = (int)adventure["failureReward"];
        data["activeAdventures"][userId]["timestamp"] = DateTime.UtcNow.ToString("o");

        File.WriteAllText(dataPath, data.ToString());

        // Calculate user's modifier
        int totalAdventures = (int)(data["users"][userId]["totalAdventures"] ?? 0);
        int modifier = Math.Min(totalAdventures / 10, 3); // +1 per 10 adventures, max +3

        string message = $"🗡️ @{userName}'s Adventure: {title}\n";
        message += $"📖 {description}\n";
        message += $"🎲 Challenge: Make a {challenge} saving throw! (DC {dc}, your modifier: +{modifier})\n";
        message += $"Type !save to attempt the challenge!";

        CPH.SendMessage(message);

        return true;
    }
}
